accepted:
.gz-sheet{
        /* Mürekkep tonları tek yerden */
        --gz-ink: #231c0f;
        --gz-ink-soft: rgba(35,28,15,.76);
        --gz-ink-faint: rgba(35,28,15,.52);
        --gz-rule: rgba(35,28,15,.55);
        /* Dizgi yazı tipleri: logo / başlık / metin */
        --gz-face-mast: 'UnifrakturMaguntia', 'Playfair Display', Georgia, serif;
        --gz-face-display: 'Playfair Display', Georgia, 'Times New Roman', serif;
        --gz-face-text: 'Old Standard TT', Georgia, 'Times New Roman', serif;

        position: relative;
        isolation: isolate;
        color: var(--gz-ink);
        font-family: var(--gz-face-text);
        border-radius: 0;
        /* Mürekkebin kağıda hafifçe yayılması (dot gain) — tüm dizgiye miras kalır */
        text-shadow: 0 0 .4px rgba(35,28,15,.5);
        /* Eski gazete kağıdı: düz krem taban + kenar tanlaması + küf (foxing)
           lekeleri. Dikey gradyan rampası bilerek yok — asıl düzensizliği
           .gz-grain katmanındaki turbulence veriyor. */
        background-color: #ece0c2;
        background-image:
          radial-gradient(circle 9px at 18% 23%, rgba(132,90,36,.16), transparent 70%),
          radial-gradient(circle 5px at 74% 11%, rgba(132,90,36,.15), transparent 72%),
          radial-gradient(circle 13px at 61% 46%, rgba(120,82,32,.10), transparent 75%),
          radial-gradient(circle 7px at 9% 66%, rgba(132,90,36,.15), transparent 70%),
          radial-gradient(circle 4px at 88% 57%, rgba(132,90,36,.18), transparent 68%),
          radial-gradient(circle 11px at 36% 82%, rgba(120,82,32,.12), transparent 74%),
          radial-gradient(circle 6px at 82% 88%, rgba(132,90,36,.15), transparent 70%),
          radial-gradient(circle 8px at 51% 95%, rgba(120,82,32,.11), transparent 72%),
          /* asimetrik iki vinyet — simetrik elips "sahte" duruyordu */
          radial-gradient(140% 92% at 42% 38%, transparent 54%, rgba(112,80,30,.16) 86%, rgba(86,60,22,.30) 100%),
          radial-gradient(92% 130% at 66% 62%, transparent 60%, rgba(104,74,28,.12) 90%, rgba(80,56,20,.22) 100%),
          /* destede üst üste durmuş kağıdın kenar tanlaması */
          linear-gradient(90deg, rgba(104,74,28,.20), transparent 3.5%, transparent 96.5%, rgba(104,74,28,.20)),
          linear-gradient(180deg, rgba(104,74,28,.18), transparent 2.5%, transparent 97.5%, rgba(104,74,28,.22));
        box-shadow:
          inset 0 0 0 1px rgba(120,90,36,.16),
          /* yüzeye değen kağıt: sıkı temas gölgesi, havada süzülmüyor */
          0 1px 2px rgba(0,0,0,.4),
          0 10px 18px -8px rgba(0,0,0,.45);
      }

      /* Kağıt dokusu: lekelenme + lif + tırtıl, üçü de çarpım karışımıyla */
      .gz-grain{
        position: absolute;
        inset: 0;
        z-index: 5;
        pointer-events: none;
        mix-blend-mode: multiply;
        background-image: ${…}, ${…}, ${…};
        background-size: 700px 700px, 320px 320px, 160px 160px;
        opacity: .42;
      }

      /* Arka yüzün mürekkebi — gerçek gazete kağıdı ince olduğu için arka
         sayfanın dizgisi hafifçe vurur. Aynalanmış satırlar + sütun boşlukları. */
      .gz-showthrough{
        position: absolute;
        inset: 0;
        z-index: -1;
        pointer-events: none;
        /* Sadece sezilecek kadar: daha koyu olduğunda kağıt değil dokuma görünüyor */
        opacity: .032;
        transform: scaleX(-1);
        background-image: repeating-linear-gradient(
          180deg,
          rgba(60,44,18,.9) 0 1.1px,
          transparent 1.1px 6.5px
        );
        /* Sütun boşlukları — keskin kenar bırakmaması için yumuşak geçişli */
        -webkit-mask-image: repeating-linear-gradient(90deg, #000 0 26%, transparent 31% 33%);
        mask-image: repeating-linear-gradient(90deg, #000 0 26%, transparent 31% 33%);
      }

      /* ── Manşet (masthead) ── */
      .gz-ear{
        font-family: var(--gz-face-text);
        font-size: 7px;
        line-height: 1.4;
        letter-spacing: .06em;
        text-transform: uppercase;
        color: var(--gz-ink-soft);
        border: 1px solid var(--gz-rule);
        padding: 2px 4px;
        text-align: center;
        flex-shrink: 0;
        max-width: 58px;
      }
      .gz-masthead{
        text-align: center;
        font-family: var(--gz-face-mast);
        font-weight: 400;
        /* Kulakların arasına sığmalı: dar ekranda taşmaması için ölçek düşük */
        font-size: clamp(1.2rem, 5.9vw, 3.3rem);
        line-height: 1.02;
        letter-spacing: .012em;
        color: #1d180c;
        /* Klişenin ağır basmış mürekkebi */
        text-shadow: 0 0 .7px rgba(29,24,12,.85), .3px .4px 0 rgba(255,255,255,.22);
        white-space: nowrap;
      }
      .gz-masthead-sub{
        margin-top: 4px;
        text-align: center;
        font-size: 8px;
        font-variant: small-caps;
        letter-spacing: .3em;
        color: var(--gz-ink-soft);
      }
      .gz-rule-double{ border-bottom: 3.5px double var(--gz-ink); opacity: .82; }
      .gz-rule-thick{ border-bottom: 2px solid var(--gz-ink); opacity: .8; }
      .gz-rule-thin{ border-bottom: 1px solid var(--gz-rule); }
      .gz-rule-hair{ border-bottom: 1px solid rgba(35,28,15,.3); }
      .gz-dateline{
        display: flex;
        align-items: baseline;
        justify-content: space-between;
        gap: 8px;
        padding: 4px 2px;
        font-size: 8.5px;
        font-variant: small-caps;
        letter-spacing: .1em;
        color: var(--gz-ink-soft);
        white-space: nowrap;
      }
      .gz-dateline > span{ overflow: hidden; text-overflow: ellipsis; }

      /* ── Basılı fotoğraf: yarım ton tramı 45°'ye döndürülmüş ── */
      .gz-photo-wrap{
        position: relative;
        display: block;
        overflow: hidden;
        background: #d5c49c;
        border: 1px solid rgba(35,28,15,.72);
        box-shadow: inset 0 0 0 1px rgba(255,255,255,.26);
      }
      .gz-photo{
        display: block;
        width: 100%;
        height: 100%;
        object-fit: cover;
        /* Gazete kağıdının ton aralığı dar ve sıkışıktır: mürekkep emici kağıtta
           tam siyaha inemez, gölgeler çamurlu griye oturur. Bu yüzden kontrast
           artırılmıyor, aksine parlaklık kaldırılıyor — hem daha sahici hem de
           koyu fotoğraflar (gece çekimleri, uydu görüntüleri) okunur kalıyor.
           Üstteki yarım ton katmanı zaten çarpım ile karartıyor.
           blur mürekkep yayılmasını (dot gain) taklit eder. */
        filter: grayscale(1) contrast(1.05) brightness(1.28) sepia(.32) blur(.2px);
      }
      .gz-photo-wrap::after{
        content: "";
        position: absolute;
        /* Döndürülmüş tramın köşeleri boş kalmasın diye kutudan bolca taşırılıyor */
        inset: -80%;
        transform: rotate(45deg);
        pointer-events: none;
        mix-blend-mode: multiply;
        opacity: .36;
        /* İki nokta katmanı, hafif kaydırılmış: baskı kaçıklığı + mürekkep yayılması */
        background-image:
          radial-gradient(circle, rgba(38,30,16,.85) .6px, transparent 1.05px),
          radial-gradient(circle, rgba(38,30,16,.32) .5px, transparent .95px);
        background-size: 3.4px 3.4px, 3.4px 3.4px;
        background-position: 0 0, .8px .55px;
      }
      .gz-photo-wrap::before{
        content: "";
        position: absolute;
        inset: 0;
        z-index: 1;
        pointer-events: none;
        background: radial-gradient(118% 100% at 50% 44%, transparent 66%, rgba(56,40,16,.22) 100%);
      }
      .gz-caption{
        margin-top: 3px;
        font-size: 8.5px;
        font-style: italic;
        letter-spacing: .03em;
        color: var(--gz-ink-faint);
        line-height: 1.35;
      }

      /* ── Dizgi tipografisi ── */
      .gz-kicker{
        font-family: var(--gz-face-display);
        font-size: 8.5px;
        font-weight: 700;
        letter-spacing: .24em;
        text-transform: uppercase;
        color: var(--gz-ink-soft);
        display: flex;
        align-items: center;
        gap: 8px;
      }
      .gz-kicker::before, .gz-kicker::after{
        content: "";
        flex: 1;
        border-bottom: 1px solid var(--gz-rule);
      }
      .gz-headline{
        font-family: var(--gz-face-display);
        font-weight: 900;
        line-height: 1.05;
        letter-spacing: -.012em;
        color: #1d180c;
        text-wrap: balance;
      }
      /* Manşetin altındaki italik ara başlık */
      .gz-deck{
        font-family: var(--gz-face-display);
        font-style: italic;
        font-weight: 700;
        line-height: 1.28;
        color: var(--gz-ink-soft);
        text-wrap: balance;
      }
      .gz-just{
        text-align: justify;
        hyphens: auto;
        -webkit-hyphens: auto;
        hyphenate-limit-chars: 6 3 3;
        word-break: break-word;
      }
      /* Sütun dizgisi — saç teli sütun cetvelleriyle */
      .gz-cols{
        column-gap: 14px;
        column-rule: 1px solid rgba(35,28,15,.3);
      }
      .gz-cols--2{ columns: 2; }
      .gz-cols--3{ columns: 2; }
      /* Uzun makale gövdesi: dar ekranda tek, geniş ekranda çift sütun */
      .gz-cols--wide{ columns: 1; }
      @media (min-width: 640px){
        /* Geniş ekranda broadsheet dizgisi: sütunlar daralır, satırlar kısalır */
        .gz-cols--2{ columns: 3; }
        .gz-cols--3{ columns: 3; }
        .gz-cols--wide{ columns: 2; }
        .gz-cols{ column-gap: 18px; }
      }
      /* Sütun akışında başlık en altta yalnız kalmasın */
      .gz-cols h3, .gz-cols blockquote, .gz-cols ul{
        break-inside: avoid;
        -webkit-column-break-inside: avoid;
      }
      .gz-cols h3{ break-after: avoid; }
      /* Sütun akışında bölünmemesi gereken haber bloğu */
      .gz-story{
        break-inside: avoid;
        -webkit-column-break-inside: avoid;
        margin-bottom: 11px;
        padding-bottom: 9px;
        border-bottom: 1px solid rgba(35,28,15,.22);
      }
      .gz-story:last-child{ border-bottom: 0; }
      .gz-byline{
        font-size: 8px;
        font-variant: small-caps;
        letter-spacing: .1em;
        color: var(--gz-ink-faint);
        display: flex;
        gap: 5px;
        align-items: baseline;
        min-width: 0;
      }
      .gz-byline .gz-src{
        font-weight: 700;
        color: var(--gz-ink-soft);
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
      }
      /* Haberin devamı başka sayfada — gerçek gazetenin atlama satırı */
      .gz-jump{
        font-size: 9.5px;
        font-style: italic;
        color: var(--gz-ink-faint);
        letter-spacing: .03em;
        text-align: right;
      }
      /* Gömme büyük harf — makale ilk paragrafı */
      .gz-dropcap::first-letter{
        float: left;
        font-family: var(--gz-face-display);
        font-size: 3.1em;
        line-height: .8;
        font-weight: 900;
        padding: 4px 6px 0 0;
        color: #1d180c;
      }
      .gz-end{
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 10px;
        font-size: 10px;
        letter-spacing: .3em;
        color: var(--gz-ink-faint);
      }
      .gz-end::before, .gz-end::after{
        content: "";
        width: 46px;
        border-bottom: 1px solid var(--gz-rule);
      }
      /* Sayfa altı folyosu */
      .gz-folio{
        display: flex;
        align-items: baseline;
        justify-content: center;
        gap: 10px;
        font-size: 8.5px;
        font-variant: small-caps;
        letter-spacing: .16em;
        color: var(--gz-ink-soft);
      }

      /* Cetvelli departman kutusu — hava durumu, ilan, telgraf haberleri */
      .gz-box{
        border: 1px solid var(--gz-rule);
        padding: 7px 9px 8px;
        box-shadow: inset 0 0 0 3px rgba(35,28,15,.06);
      }
      .gz-box-title{
        font-family: var(--gz-face-display);
        font-size: 9px;
        font-weight: 700;
        letter-spacing: .2em;
        text-transform: uppercase;
        text-align: center;
        color: var(--gz-ink);
        border-bottom: 1px solid var(--gz-rule);
        padding-bottom: 4px;
        margin-bottom: 6px;
      }

      /* Basılı uyarı kutusu (hata / özet düştü notu) */
      .gz-notice{
        border: 1px dashed rgba(122,44,18,.55);
        background: rgba(154,74,28,.07);
        color: rgba(96,46,16,.9);
        padding: 7px 10px;
        font-size: 10.5px;
        line-height: 1.45;
        font-style: italic;
      }

      /* Dizgi yükleniyor iskeleti — soluk mürekkep satırları */
      .gz-skel{
        border-radius: 0;
        background: linear-gradient(90deg, rgba(35,28,15,.14), rgba(35,28,15,.08) 55%, rgba(35,28,15,.14));
      }

      /* Ekran içinde dokunulabilir makale blokları */
      .gz-tap{
        display: block;
        width: 100%;
        text-align: left;
        color: inherit;
      }
      .gz-tap:active{ background: rgba(35,28,15,.06); }
      .gz-tap:focus-visible{ outline: 2px solid rgba(122,92,26,.7); outline-offset: 2px; }

/* ── Kasa: fotoğrafı kırpan kutu ── */
      .iw-device{
        position: relative;
        isolation: isolate;
        overflow: hidden;
        align-self: start;
        border-radius: 14px;
        border: 1px solid rgba(202,160,68,.34);
        background: #14100c;
        box-shadow:
          0 2px 4px rgba(0,0,0,.45),
          0 10px 22px rgba(0,0,0,.5),
          inset 0 1px 0 rgba(255,232,170,.14);
      }
      .iw-small{ grid-column: span 1; }
      .iw-medium{ grid-column: span 2; }

      .iw-photo{
        position: absolute;
        z-index: 0;
        max-width: none;
        object-fit: fill;
        user-select: none;
        pointer-events: none;
      }
      /* Fotoğraf gelmezse okumalar yine de okunur kalsın. */
      .iw-device--fallback{
        background: linear-gradient(160deg, #2a211a 0%, #16100b 100%);
      }

      /*
        Ortak ışık: altı fotoğraf altı ayrı stüdyoda çekildi. Hepsinin üstünden
        aynı vinyet ve aynı köşegen parlama geçince tek bir dolabın içindeki
        enstrümanlar gibi dururlar. Canlı yüzeylerin (z-index 2) altında kalır.
      */
      .iw-grade{
        position: absolute;
        z-index: 1;
        inset: 0;
        pointer-events: none;
        background:
          linear-gradient(128deg, rgba(255,244,214,.14) 0%, rgba(255,244,214,.03) 26%, transparent 46%),
          radial-gradient(120% 110% at 34% 26%, rgba(255,236,196,.1) 0%, transparent 58%),
          radial-gradient(130% 120% at 50% 52%, transparent 46%, rgba(10,6,2,.34) 84%, rgba(6,3,1,.6) 100%);
      }

      /* ── Üst şerit: pirinç plaka + eylem ── */
      .iw-top{
        position: absolute;
        z-index: 6;
        top: 0;
        left: 0;
        right: 0;
        display: flex;
        align-items: flex-start;
        justify-content: space-between;
        gap: 6px;
        padding: 7px 8px 14px;
        background: linear-gradient(180deg, rgba(6,4,2,.7) 0%, rgba(6,4,2,.34) 55%, transparent 100%);
        pointer-events: none;
      }
      .iw-top > *{ pointer-events: auto; }

      /* Pirinç künye: fırçalanmış yüzey, iki vida, kazınmış harfler. */
      .iw-plate{
        position: relative;
        font-family: Georgia, 'Times New Roman', serif;
        font-size: 9px;
        font-weight: 600;
        line-height: 1.1;
        letter-spacing: .12em;
        color: #3a2b10;
        text-transform: uppercase;
        text-align: center;
        padding: 3px 11px;
        border-radius: 3px;
        max-width: 100%;
        text-shadow: 0 1px 0 rgba(255,255,255,.5), 0 -1px 0 rgba(0,0,0,.22);
        background:
          radial-gradient(circle 1.7px at 5px 50%, #6b4e16 0 52%, rgba(0,0,0,.45) 62%, transparent 72%),
          radial-gradient(circle 1.7px at calc(100% - 5px) 50%, #6b4e16 0 52%, rgba(0,0,0,.45) 62%, transparent 72%),
          repeating-linear-gradient(94deg, rgba(255,255,255,.09) 0 1px, rgba(120,88,24,.05) 1px 3px),
          linear-gradient(180deg, #f8e7ab 0%, #dfba63 48%, #b98f34 100%);
        box-shadow:
          inset 0 1px 1px rgba(255,255,255,.6),
          inset 0 -1px 1px rgba(0,0,0,.4),
          0 1px 3px rgba(0,0,0,.6);
      }

      /* ── Alt şerit: okumalar. Fotoğraf ne olursa olsun kontrast burada. ── */
      .iw-readout{
        position: absolute;
        z-index: 6;
        bottom: 0;
        left: 0;
        right: 0;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 1px;
        padding: 15px 8px 7px;
        background: linear-gradient(0deg, rgba(5,3,1,.92) 0%, rgba(5,3,1,.68) 46%, transparent 100%);
      }
      /* Şeridi kasaya bağlayan pirinç kılcal çizgi. */
      .iw-readout::before{
        content: "";
        position: absolute;
        left: 10%;
        right: 10%;
        top: 12px;
        height: 1px;
        background: linear-gradient(90deg, transparent, rgba(226,190,110,.4) 22%, rgba(226,190,110,.4) 78%, transparent);
      }
      /* İki okumayı yan yana koyan satır (doğuş/batış gibi). */
      .iw-split{
        display: flex;
        width: 100%;
        justify-content: space-between;
        align-items: flex-end;
        padding-inline: 10px;
      }
      .iw-readout-cell{
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 1px;
      }

      .iw-digital{
        font-family: Georgia, 'Times New Roman', serif;
        font-variant-numeric: tabular-nums;
        font-size: 15px;
        font-weight: 700;
        color: #f7e6ac;
        text-shadow: 0 1px 2px rgba(0,0,0,.9), 0 0 10px rgba(226,180,90,.28);
        letter-spacing: .08em;
        line-height: 1;
      }
      .iw-sub{
        font-family: Georgia, 'Times New Roman', serif;
        font-size: 8px;
        color: #d8cba6;
        text-shadow: 0 1px 2px rgba(0,0,0,.85);
        letter-spacing: .08em;
        max-width: 100%;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        line-height: 1.2;
      }

      /* ── Kadran: fotoğraftaki donmuş kadranı canlı SVG yüzey örter ──
         Kutu yalnızca daireyi konumlandırır; bütün çizim SVG'de. Gölge,
         yüzeyi fotoğrafın camının altına oturtur. */
      .iw-dial{
        position: absolute;
        z-index: 2;
        border-radius: 50%;
        box-shadow:
          0 0 5px 2px rgba(16,10,3,.4),
          inset 0 1px 3px rgba(0,0,0,.3);
      }
      .iw-svg{
        display: block;
        width: 100%;
        height: 100%;
        /* Yüzey içindeki karışım modları fotoğrafa taşmasın. */
        isolation: isolate;
      }

      /* ── LCD: fotoğraftaki renkli ekranın üstüne canlı sayfa ──
         SGN-500'ün ekranı beyaz zeminli renkli bir LCD; düzen cihazınkini
         izler: sarı başlık şeridi, kutulanmış küçük alanlar, ortada iri mevki
         satırları. Alan adları küçük ve gri, değerler kalın siyah. */
      .iw-screen{
        position: absolute;
        z-index: 2;
        display: flex;
        flex-direction: column;
        border-radius: 2px;
        overflow: hidden;
        background: linear-gradient(180deg, #f4f4f0 0%, #e2e4de 100%);
        box-shadow:
          0 0 0 1px rgba(0,0,0,.7),
          inset 0 0 10px rgba(20,30,20,.16);
        font-family: ui-monospace, SFMono-Regular, Menlo, 'Courier New', monospace;
        color: #16191c;
        line-height: 1.2;
      }
      /* Ekran camı: piksel ızgarası, tarama satırları, köşegen parlama */
      .iw-screen::after{
        content: "";
        position: absolute;
        inset: 0;
        pointer-events: none;
        background:
          linear-gradient(112deg, rgba(255,255,255,.4) 0%, rgba(255,255,255,.08) 20%, transparent 38%),
          repeating-linear-gradient(90deg, rgba(0,0,0,.05) 0 1px, transparent 1px 2px),
          repeating-linear-gradient(180deg, rgba(0,0,0,.07) 0 1px, transparent 1px 3px);
      }

      /* Başlık şeridi: fotoğrafta pusula bandının bulunduğu sarı kuşak. */
      .iw-lcd-bar{
        display: flex;
        justify-content: space-between;
        gap: 6px;
        padding: 1px 4px;
        font-size: 6.5px;
        font-weight: 700;
        letter-spacing: .08em;
        color: #3c3308;
        background: linear-gradient(180deg, #e8ca45 0%, #cdac2c 100%);
        border-bottom: 1px solid rgba(0,0,0,.5);
      }
      .iw-lcd-place{
        min-width: 0;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
      }

      /* Alan satırı: cihazdaki gibi üç eşit kutu, aralarında ince ayırıcı. */
      .iw-lcd-cells{
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        border-bottom: 1px solid rgba(0,0,0,.35);
      }
      .iw-lcd-cells:last-child{ border-bottom: 0; border-top: 1px solid rgba(0,0,0,.35); }
      .iw-lcd-cell{
        display: flex;
        flex-direction: column;
        min-width: 0;
        padding: 0 3px 1px;
        border-right: 1px solid rgba(0,0,0,.3);
      }
      .iw-lcd-cell:last-child{ border-right: 0; }
      .iw-lcd-key{
        margin: 0 -3px 1px;
        padding: 0 3px;
        font-size: 5.2px;
        letter-spacing: .1em;
        color: #5c6167;
        background: rgba(15,25,35,.08);
      }
      .iw-lcd-val{
        font-size: 9px;
        font-weight: 700;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
      }
      .iw-lcd-small{ font-size: 7.5px; }
      .iw-lcd-warn{ color: #a3520f; }

      /* Mevki: ekranın ortasını kaplayan iki iri satır. */
      .iw-lcd-fix{
        flex: 1;
        display: flex;
        flex-direction: column;
        justify-content: center;
        gap: 1px;
        padding: 1px 5px;
        min-height: 0;
      }
      .iw-lcd-coord{
        font-size: 12.8px;
        font-weight: 700;
        letter-spacing: -.03em;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
      }

      .iw-btn{
        display: flex;
        align-items: center;
        justify-content: center;
        width: 24px;
        height: 24px;
        flex-shrink: 0;
        border-radius: 50%;
        color: #f2d98a;
        background:
          radial-gradient(circle at 32% 26%, rgba(255,255,255,.2) 0 12%, transparent 34%),
          radial-gradient(circle at 35% 30%, #4a3b2c, #241a10);
        border: 1px solid rgba(202,160,68,.5);
        box-shadow: 0 1px 3px rgba(0,0,0,.6), inset 0 1px 0 rgba(242,217,138,.15);
        transition: transform .12s ease;
      }
      .iw-btn:active{ transform: scale(.9); }

      /* ── Termometre: fotoğrafın kılcalını örten cam kılcal ──
         Tüp saydam: fotoğrafın basılı taksimatı arkasından görünür, yalnızca
         kılcalın kendisi yeniden boyanır. */
      .iw-tube{
        position: absolute;
        z-index: 2;
        border-radius: 2px;
        /* Neredeyse saydam: fotoğrafın basılı taksimatı arkadan okunmaya devam
           etsin, yalnızca kılcalın camı yeniden ışıklansın. */
        background:
          linear-gradient(90deg,
            rgba(255,255,255,.3) 0%,
            rgba(255,255,255,.34) 20%,
            rgba(148,156,154,.12) 54%,
            rgba(72,78,76,.22) 100%);
        box-shadow: inset 0 0 2px rgba(0,0,0,.3);
      }
      .iw-mercury{
        position: absolute;
        left: 0;
        right: 0;
        bottom: 0;
        /* Silindir: sol kenarda ışık, sağ kenarda gölge. */
        background:
          linear-gradient(90deg, #5d0f0f 0%, #a9231d 24%, #e0685c 39%, #a81f19 62%, #4d0c0c 100%);
        box-shadow:
          0 0 5px rgba(150,26,20,.5),
          inset 0 -8px 8px rgba(0,0,0,.22);
      }
      /* Menisküs: sıvının ucundaki kubbe. */
      .iw-mercury::after{
        content: "";
        position: absolute;
        left: -4%;
        right: -4%;
        top: -2px;
        height: 3.6px;
        border-radius: 50%;
        background: radial-gradient(ellipse at 32% 26%, #e8867a 0%, #b32a22 52%, #6d1210 100%);
      }

      /* ── Lombar camı ── */
      .iw-glass{
        position: absolute;
        z-index: 2;
        border-radius: 50%;
        overflow: hidden;
      }
      /* Güneşin camın dışına, madeni çerçeveye vuran ışığı. */
      .iw-spill{
        position: absolute;
        z-index: 3;
        width: 62%;
        aspect-ratio: 1;
        transform: translate(-50%, -50%);
        border-radius: 50%;
        pointer-events: none;
        mix-blend-mode: screen;
        filter: blur(6px);
      }
      /* Text sits outside the calibrated photo region. */
      .home-instruments .iw-device {
        min-width: 0;
        border-radius: 8px;
        border: 1px solid var(--instrument-line);
        background: var(--instrument-surface);
        color: var(--instrument-text);
        box-shadow: none;
      }
      .home-instruments .iw-visual {
        position: relative;
        isolation: isolate;
        overflow: hidden;
        background: var(--instrument-visual);
      }
      .home-instruments .iw-top {
        position: relative;
        align-items: center;
        min-height: 44px;
        padding: 8px 12px;
        background: var(--instrument-surface);
        border-bottom: 1px solid var(--instrument-line);
      }
      .home-instruments .iw-plate {
        font-family: inherit;
        font-size: 12px;
        font-weight: 600;
        line-height: 1.4;
        letter-spacing: 0;
        text-transform: none;
        text-align: left;
        color: var(--instrument-muted);
        padding: 0;
        background: none;
        box-shadow: none;
        text-shadow: none;
      }
      .home-instruments .iw-grade {
        background: none;
      }
      .home-instruments .iw-readout {
        position: relative;
        min-height: 66px;
        justify-content: center;
        gap: 5px;
        padding: 12px 8px;
        border-top: 1px solid var(--instrument-line);
        background: var(--instrument-surface);
      }
      .home-instruments .iw-readout::before { display: none; }
      .home-instruments .iw-digital {
        font-family: 'JetBrains Mono', ui-monospace, monospace;
        font-size: 22px;
        font-weight: 500;
        line-height: 1.2;
        letter-spacing: 0;
        color: var(--instrument-text);
        text-shadow: none;
      }
      .home-instruments .iw-sub {
        font-family: inherit;
        font-size: 11px;
        letter-spacing: 0;
        line-height: 1.4;
        color: var(--instrument-muted);
        text-shadow: none;
      }
      .home-instruments .iw-readout-cell { gap: 5px; }
      .iw-position-action { color: var(--instrument-muted); }
      .iw-position-body { padding: 16px; }
      .iw-position-place {
        margin-bottom: 14px;
        color: var(--instrument-muted);
        font-size: 12px;
        overflow-wrap: anywhere;
      }
      .iw-position-coords {
        display: grid;
        gap: 8px;
        font-family: 'JetBrains Mono', ui-monospace, monospace;
        font-size: 18px;
        font-variant-numeric: tabular-nums;
        line-height: 1.5;
        letter-spacing: 0;
      }
      .iw-position-decimal {
        margin-top: 8px;
        color: var(--instrument-muted);
        font-size: 11px;
        overflow-wrap: anywhere;
      }
      .iw-position-details {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 8px;
        padding: 12px 16px;
        border-top: 1px solid var(--instrument-line);
        margin: 0;
      }
      .iw-position-details dt {
        font-size: 11px;
        color: var(--instrument-muted);
      }
      .iw-position-details dd {
        margin: 4px 0 0;
        font-size: 12px;
        font-variant-numeric: tabular-nums;
        overflow-wrap: anywhere;
      }
      .iw-position-source { color: var(--instrument-accent); }
      .iw-position-source--approximate { color: var(--instrument-warning); }
      @media (max-width: 359px) {
        .iw-position-coords { font-size: 16px; }
      }
